1: """What an agent sees of a browser tab and what it can do there.
2: 
3: `Tab.observe()` renders any web page as accessible text: what a screen reader would announce, with every control
4: numbered so the model can act on it. Nothing here knows a particular website. It reads labels, descriptions,
5: tooltips, embedded frames and collapsed sections, drops invisible characters, and leaves every choice of where to go
6: and what to read to the model.
7: """
8: from __future__ import annotations
9: 
10: import asyncio
11: import io
12: import re
13: import zipfile
14: from html.parser import HTMLParser
15: from urllib.parse import urljoin, urlparse
16: 
17: # Renders one document. Returns {text, next}: `text` with ⟦FRAME:n⟧ markers where embedded documents go, `next` the
18: # first unused element id. Every control gets data-aid="<id>" so it can be found again.
19: SNAPSHOT_JS = r"""
20: (startId) => {
21:   const ZW = /[​-‏⁠-⁤﻿­͏؜᠎]/g;
22:   const SKIP = new Set(['SCRIPT','STYLE','NOSCRIPT','TEMPLATE','HEAD','META','LINK','TITLE','OPTION','OPTGROUP',
23:                         'DATALIST','SOURCE','TRACK','PARAM']);
24:   const CONTROL = new Set(['INPUT','SELECT','TEXTAREA','BUTTON']);
25:   let nextId = startId;
26:   document.querySelectorAll('[data-aid]').forEach(e => e.removeAttribute('data-aid'));
27:   const described = new Set();
28:   document.querySelectorAll('[aria-describedby],[aria-labelledby]').forEach(e => {
29:     ((e.getAttribute('aria-describedby') || '') + ' ' + (e.getAttribute('aria-labelledby') || ''))
30:       .split(/\s+/).forEach(id => id && described.add(id));
31:   });
32:   const clean = s => (s || '').replace(ZW, '').replace(/\s+/g, ' ').trim();
33:   const cut = (s, n) => s.length > n ? s.slice(0, n) + '…' : s;
34:   const styleOf = el => getComputedStyle(el);
35:   const cssHidden = el => { const cs = styleOf(el); return cs.display === 'none' || cs.visibility === 'hidden' || cs.visibility === 'collapse'; };
36:   const isHidden = el => el.hidden || el.getAttribute('aria-hidden') === 'true' || (el.tagName === 'INPUT' && el.type === 'hidden') || cssHidden(el);
37:   const pseudo = (el, which) => {
38:     let c; try { c = getComputedStyle(el, which).content; } catch (e) { return ''; }
39:     if (!c || c === 'none' || c === 'normal') return '';
40:     const attr = c.match(/^attr\(([^)]+)\)$/);
41:     if (attr) return el.getAttribute(attr[1].trim()) || '';
42:     const quoted = c.match(/^"((?:[^"\\]|\\.)*)"$/) || c.match(/^'((?:[^'\\]|\\.)*)'$/);
43:     return quoted ? quoted[1].replace(/\\(.)/g, '$1') : '';
44:   };
45:   const reversed = el => { const cs = styleOf(el); return cs.direction === 'rtl' && /bidi-override/.test(cs.unicodeBidi); };
46:   // The text a screen reader would read for a subtree. `force` reads a hidden root (tooltips, descriptions).
47:   const textOf = (node, force) => {
48:     if (node.nodeType === 3) return node.nodeValue;
49:     if (node.nodeType !== 1 || SKIP.has(node.tagName)) return '';
50:     if (!force && isHidden(node)) return '';
51:     const label = node.getAttribute('aria-label');
52:     const role = node.getAttribute('role');
53:     const tag = node.tagName.toUpperCase();
54:     if (label && (role === 'img' || tag === 'CANVAS' || tag === 'SVG' || tag === 'IMG')) return ' ' + label + ' ';
55:     if (tag === 'IMG') return ' ' + (node.getAttribute('alt') || '') + ' ';
56:     if (tag === 'BR') return '\n';
57:     if (CONTROL.has(tag) && tag !== 'BUTTON') return '';
58:     let s = pseudo(node, '::before');
59:     for (const child of node.childNodes) s += textOf(child, false);
60:     s += pseudo(node, '::after');
61:     if (reversed(node)) s = [...s].reverse().join('');
62:     return s;
63:   };
64:   const byIds = ids => clean((ids || '').split(/\s+/).map(id => { const e = id && document.getElementById(id); return e ? textOf(e, true) : ''; }).join(' '));
65:   const nameOf = el => clean(byIds(el.getAttribute('aria-labelledby')) || el.getAttribute('aria-label') || textOf(el, false) || el.getAttribute('title') || el.getAttribute('value') || '');
66:   const labelOf = el => {
67:     const parts = [byIds(el.getAttribute('aria-labelledby')), el.getAttribute('aria-label') || ''];
68:     if (el.labels) for (const l of el.labels) parts.push(textOf(l, false));
69:     let s = clean(parts.join(' '));
70:     if (!s) s = clean(el.getAttribute('placeholder') || el.getAttribute('title') || el.getAttribute('name') || '');
71:     return s;
72:   };
73:   const disabled = el => el.disabled === true || el.getAttribute('aria-disabled') === 'true' || !!el.closest('fieldset[disabled],[inert]');
74:   const dataHints = el => {
75:     const out = [];
76:     for (const a of el.attributes) {
77:       if (!a.name.startsWith('data-') || a.name === 'data-aid' || out.length >= 3) continue;
78:       out.push(a.value ? a.name + '=' + cut(clean(a.value), 60) : a.name);
79:     }
80:     return out.length ? ' {' + out.join(' ') + '}' : '';
81:   };
82:   const hrefOf = el => {
83:     const raw = el.getAttribute('href') || '';
84:     try { const u = new URL(raw, location.href); return u.origin === location.origin ? u.pathname + u.search + u.hash : u.href; }
85:     catch (e) { return raw; }
86:   };
87:   const q = s => '"' + cut(clean(s), 160).replace(/"/g, "'") + '"';
88:   const flags = el => (disabled(el) ? ' (disabled)' : '') + (el.required ? ' (required)' : '') + (el.readOnly ? ' (read-only)' : '');
89:   const descr = el => { const d = byIds(el.getAttribute('aria-describedby')); return d ? ' (described: ' + q(d) + ')' : ''; };
90:   const tag = (el, collapsed) => { const id = nextId++; el.setAttribute('data-aid', String(id)); return '[' + id + ']' + (collapsed ? ' (in collapsed menu)' : ''); };
91:   // One control as text, or null when `el` is not a control.
92:   const control = (el, collapsed) => {
93:     const t = el.tagName.toUpperCase(), role = el.getAttribute('role') || '', type = (el.getAttribute('type') || '').toLowerCase();
94:     if (t === 'A' && el.hasAttribute('href')) return tag(el, collapsed) + ' link ' + q(nameOf(el)) + ' -> ' + cut(hrefOf(el), 200) + dataHints(el) + descr(el);
95:     if (t === 'BUTTON' || (t === 'INPUT' && ['submit', 'button', 'reset', 'image'].includes(type)) || role === 'button') {
96:       const nv = el.getAttribute('name') ? ' ' + el.getAttribute('name') + '=' + (el.getAttribute('value') || '') : '';
97:       return tag(el, collapsed) + ' button ' + q(nameOf(el)) + nv + flags(el) + dataHints(el) + descr(el);
98:     }
99:     if (t === 'INPUT' && (type === 'checkbox' || type === 'radio'))
100:       return tag(el, collapsed) + ' ' + type + ' ' + q(labelOf(el)) + (el.checked ? ' [checked]' : ' [unchecked]') + (el.name ? ' name=' + el.name : '') + (el.value && el.value !== 'on' ? ' value=' + el.value : '') + flags(el);
101:     if (t === 'INPUT' && type === 'range')
102:       return tag(el, collapsed) + ' slider ' + q(labelOf(el)) + ' value=' + el.value + ' min=' + (el.min || 0) + ' max=' + (el.max || 100) + flags(el);
103:     if (t === 'INPUT' && type === 'file') return tag(el, collapsed) + ' file-upload ' + q(labelOf(el)) + flags(el);
104:     if (t === 'INPUT' || t === 'TEXTAREA') {
105:       const shown = type === 'password' ? (el.value ? '••••' : '') : el.value;
106:       return tag(el, collapsed) + ' input' + (type && type !== 'text' ? '(' + type + ')' : '') + ' ' + q(labelOf(el)) + ' value=' + q(shown) + (el.placeholder ? ' placeholder=' + q(el.placeholder) : '') + flags(el) + descr(el);
107:     }
108:     if (t === 'SELECT') {
109:       const options = [...el.options].slice(0, 80).map(o => (o.selected ? '*' : '') + (clean(o.textContent) === o.value ? q(o.value) : q(o.value) + '=' + q(o.textContent)));
110:       return tag(el, collapsed) + ' select ' + q(labelOf(el)) + flags(el) + ' options(* = selected): ' + options.join('; ') + (el.options.length > 80 ? '; …' : '');
111:     }
112:     if (t === 'SUMMARY') return tag(el, collapsed) + ' toggle ' + q(nameOf(el)) + (el.parentElement && el.parentElement.open ? ' [open]' : ' [closed]') + flags(el);
113:     if (['link', 'tab', 'menuitem', 'option', 'checkbox', 'radio', 'switch', 'treeitem'].includes(role) || el.hasAttribute('onclick') || el.isContentEditable && !el.parentElement.isContentEditable)
114:       return tag(el, collapsed) + ' ' + (role || 'clickable') + ' ' + q(nameOf(el)) + flags(el) + dataHints(el) + descr(el);
115:     return null;
116:   };
117:   const lines = [];
118:   let cur = '', inline = 0;
119:   const flush = () => { if (inline) { cur += ' '; return; } const t = cur.replace(ZW, '').replace(/[ \t ]+/g, ' ').trim(); if (t) lines.push(t); cur = ''; };
120:   const isBlock = el => { const d = styleOf(el).display; return !(d.startsWith('inline') || d === 'contents' || d === 'table-cell' || d === 'ruby'); };
